export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;

  let initialized = false;
  let prevObs = null;
  let lastAction = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };

  // Estimator state
  let uLag = 0.45;
  let kT = 22.0; // specific thrust at full collective (16 / 0.725)
  let massHat = 0.725;
  let vxHat = 0, vyHat = 0, vzHat = 0;
  let dxHat = 0, dyHat = 0, dzHat = 0;
  let dxSlow = 0, dzSlow = 0;
  let yawInt = 0;
  let rollLag = 0, pitchLag = 0;
  let rollTrim = 0, pitchTrim = 0;

  // Navigation state
  let currentGate = 0;
  let gatePhase = 'approach'; // 'approach' | 'commit'
  let alignedCount = 0;
  let startPos = { x: -2.1, y: 0.07, z: -1.65 };
  let gateExitX = -2.1;
  let gateExitY = 0.5;
  let gateExitZ = -1.65;
  let padPhase = 'approach'; // 'approach' | 'flare' | 'touchdown'

  function getDir(att) {
    const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
    const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
    const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
    const bodyX = sp * cr, bodyZ = -sr;
    return {
      x: cy * bodyX + sy * bodyZ,
      y: cp * cr,
      z: -sy * bodyX + cy * bodyZ,
    };
  }

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;

      if (!initialized) {
        initialized = true;
        startPos = { x: p.x, y: p.y, z: p.z };
        gateExitX = p.x;
        gateExitY = 0.6;
        gateExitZ = p.z;
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      } else {
        // Update lagged actuator models
        uLag += (lastAction.thrust - uLag) * (1 - Math.exp(-dt / 0.038));
        rollLag += (lastAction.roll - rollLag) * (1 - Math.exp(-dt / 0.055));
        pitchLag += (lastAction.pitch - pitchLag) * (1 - Math.exp(-dt / 0.055));

        const dirPrev = getDir(prevObs.att);
        const dirCurr = getDir(att);
        const dirAvg = {
          x: 0.5 * (dirPrev.x + dirCurr.x),
          y: 0.5 * (dirPrev.y + dirCurr.y),
          z: 0.5 * (dirPrev.z + dirCurr.z),
        };

        const airborne = p.y > 0.09 && prevObs.pos.y > 0.09;
        const drag = 0.42 / massHat;

        if (airborne) {
          // Attitude trim learning (compensates weak motor steady-state offset)
          rollTrim = clamp(rollTrim + 0.35 * (rollLag - att.roll) * dt, -0.06, 0.06);
          pitchTrim = clamp(pitchTrim + 0.35 * (pitchLag - att.pitch) * dt, -0.06, 0.06);

          const ayModel = kT * uLag * dirAvg.y - 9.81 - drag * 0.5 * (prevObs.vel.y + v.y);
          vyHat += (ayModel + dyHat) * dt;
          const vyErr = v.y - vyHat;
          vyHat += 0.45 * vyErr;
          dyHat = clamp(dyHat + 8.0 * vyErr, -6.0, 6.0);

          if (uLag > 0.25 && dirAvg.y > 0.7) {
            kT = clamp(kT + 0.9 * dyHat * dt, 15.5, 27.5);
            massHat = clamp(15.2 / kT, 0.60, 0.85);
          }

          const fSpec = Math.max(0, kT * uLag + dyHat / Math.max(0.6, dirAvg.y));
          const axModel = fSpec * dirAvg.x - drag * 0.5 * (prevObs.vel.x + v.x);
          const azModel = fSpec * dirAvg.z - drag * 0.5 * (prevObs.vel.z + v.z);

          vxHat += (axModel + dxHat) * dt;
          const vxErr = v.x - vxHat;
          vxHat += 0.50 * vxErr;
          dxHat = clamp(dxHat + 12.0 * vxErr, -8.5, 8.5);

          vzHat += (azModel + dzHat) * dt;
          const vzErr = v.z - vzHat;
          vzHat += 0.50 * vzErr;
          dzHat = clamp(dzHat + 12.0 * vzErr, -8.5, 8.5);

          dxSlow += (dxHat - dxSlow) * 0.08;
          dzSlow += (dzHat - dzSlow) * 0.08;
        } else {
          vxHat = v.x; vyHat = v.y; vzHat = v.z;
        }
      }

      prevObs = {
        pos: { x: p.x, y: p.y, z: p.z },
        vel: { x: v.x, y: v.y, z: v.z },
        att: { roll: att.roll, pitch: att.pitch, yaw: att.yaw },
      };

      // Check gate transition
      if (obs.gateIndex !== currentGate) {
        currentGate = obs.gateIndex;
        gatePhase = 'approach';
        alignedCount = 0;
        gateExitX = p.x;
        gateExitY = p.y;
        gateExitZ = p.z;
      }

      let xRef, yRef, zRef;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 6.5, kdX = 4.5;
      let kpY = 9.0, kdY = 5.2;
      let kpZ = 10.5, kdZ = 5.8;
      let maxTilt = 0.55;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;

        // Safe corridor after exiting previous gate (for gateIndex > 0)
        // Don't slew Y/Z until at least 0.14m past the previous gate plane
        const clearOfPrev = obs.gateIndex === 0 ? (p.y > 0.25) : (p.x > gateExitX + 0.14);

        if (!clearOfPrev) {
          xRef = obs.gateIndex === 0 ? p.x + 0.15 : gateExitX + 0.30;
          vxRef = obs.gateIndex === 0 ? 0.3 : 0.9;
          yRef = obs.gateIndex === 0 ? g.y : gateExitY;
          zRef = obs.gateIndex === 0 ? p.z + 0.2 * (g.z - p.z) : gateExitZ;
        } else {
