          const blend = 1 - (1 - s) * (1 - s);
          yRef = obs.gateIndex === 0 ? g.y : gateExitY + blend * (g.y - gateExitY);
          zRef = (obs.gateIndex === 0 ? startPos.z : gateExitZ) + blend * (g.z - (obs.gateIndex === 0 ? startPos.z : gateExitZ));

          // Once within 0.65m of gate X, lock Y/Z reference strictly to gate center
          if (p.x > g.x - 0.65) {
            yRef = g.y;
            zRef = g.z;
            kpY = 11.5; kdY = 6.0;
            kpZ = 13.5; kdZ = 6.5;
          }

          const ey = p.y - g.y;
          const ez = p.z - g.z;
          const eyPred = ey + 0.14 * vyHat;
          const ezPred = ez + 0.14 * vzHat;
          const gustShockZ = Math.abs(dzHat - dzSlow);

          const aligned =
            p.x > g.x - 0.55 &&
            Math.abs(ey) < 0.085 &&
            Math.abs(eyPred) < 0.105 &&
            Math.abs(vyHat) < 0.35 &&
            Math.abs(ez) < 0.045 &&
            Math.abs(ezPred) < 0.055 &&
            Math.abs(vzHat) < 0.22 &&
            gustShockZ < 1.6;

          if (gatePhase === 'approach') {
            if (aligned) alignedCount++;
            else alignedCount = Math.max(0, alignedCount - 1);

            if (alignedCount >= 4) {
              gatePhase = 'commit';
            }
          } else if (gatePhase === 'commit') {
            // Emergency abort if a strong gust pushes us off-line before we are too close to stop
            if (p.x < g.x - 0.14 && (Math.abs(ezPred) > 0.078 || Math.abs(ez) > 0.072 || Math.abs(eyPred) > 0.145)) {
              gatePhase = 'approach';
              alignedCount = 0;
            }
          }

          if (gatePhase === 'approach') {
            xRef = g.x - 0.32;
            vxRef = p.x < g.x - 0.50 ? 0.65 : 0.0;
            kpX = 7.5; kdX = 5.0;
          } else {
            // Commit through gate at brisk, steady forward speed
            xRef = g.x + 0.28;
            vxRef = 1.05;
            kpX = 6.5; kdX = 4.2;
          }
        }
      } else {
        // Gate 3 passed -> fly to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        const clearOfGate2 = p.x > 1.35 + 0.15;

        if (!clearOfGate2) {
          xRef = 1.60;
          vxRef = 0.85;
          yRef = 1.05;
          zRef = 1.05;
        } else {
          const distH = Math.hypot(pad.x - p.x, pad.z - p.z);
          const speedH = Math.hypot(vxHat, vzHat);

          xRef = pad.x;
          zRef = pad.z;
          kpX = 8.5; kdX = 5.2;
          kpZ = 8.5; kdZ = 5.2;

          if (padPhase === 'approach') {
            // Smooth glide slope down to 0.24m as we approach the pad horizontally
            yRef = clamp(0.22 + 0.75 * distH, 0.22, 1.05);
            vyRef = distH > 0.18 ? -0.35 : 0.0;
            if (distH < 0.095 && speedH < 0.28 && p.y < 0.32) {
              padPhase = 'flare';
            }
          }

          if (padPhase === 'flare') {
            if (distH > 0.135) {
              padPhase = 'approach';
            } else {
              yRef = 0.055;
              vyRef = p.y > 0.14 ? -0.32 : -0.18;
              kpY = 10.0; kdY = 6.0;
              maxTilt = 0.16;
              if (p.y <= 0.088 && distH < 0.12 && speedH < 0.35) {
                padPhase = 'touchdown';
              }
            }
          }

          if (padPhase === 'touchdown') {
            if (distH > 0.14) {
              padPhase = 'flare';
            } else {
              // Pin gently to the pad with low tilt
              maxTilt = 0.12;
              yRef = 0.02;
              vyRef = -0.15;
            }
          }
        }
      }

      // Position + velocity PD control in world frame
      const ex = clamp(xRef - p.x, -0.85, 0.85);
      const ey = clamp(yRef - p.y, -0.85, 0.85);
      const ez = clamp(zRef - p.z, -0.85, 0.85);

      const axDes = clamp(kpX * ex + kdX * (vxRef - vxHat), -4.8, 4.8);
      const ayDes = clamp(kpY * ey + kdY * (vyRef - vyHat), -4.5, 5.5);
      const azDes = clamp(kpZ * ez + kdZ * (vzRef - vzHat), -4.8, 4.8);

      const drag = 0.42 / massHat;
      const fx = axDes + drag * vxHat - dxHat;
      const fy = Math.max(2.5, ayDes + 9.81 + drag * vyHat - dyHat);
      const fz = azDes + drag * vzHat - dzHat;

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const fBodyX = cy * fx - sy * fz;
      const fBodyZ = sy * fx + cy * fz;

      let pitch = clamp(Math.atan2(fBodyX, fy) + pitchTrim, -maxTilt, maxTilt);
      let roll = clamp(Math.atan2(-fBodyZ, Math.hypot(fBodyX, fy)) + rollTrim, -maxTilt, maxTilt);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrust = clamp(fy / (kT * cosTilt), 0, 1);

      if (obs.gateIndex === 3 && padPhase === 'touchdown' && p.y <= 0.082) {
        thrust = 0.02;
        pitch = clamp(pitch, -0.10, 0.10);
        roll = clamp(roll, -0.10, 0.10);
      }

      yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-3.5 * att.yaw - 1.5 * yawInt - 0.25 * obs.rates.yaw, -2, 2);

      lastAction = { thrust, roll, pitch, yawRate };
      return lastAction;
    },
  };
}

