      let pitch = clamp(Math.atan2(fBodyX, fy), -maxTilt, maxTilt);
      let roll = clamp(Math.atan2(-fBodyZ, Math.hypot(fBodyX, fy)), -maxTilt, maxTilt);

      let thrust = clamp(fy / (kT * Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch))), 0, 1);
