export default function makeController() {
  let targetIndex = -1, phase = 'climb', integralY = 0, settle = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  // Disturbance observer state
  let prevObs = null;
  let lastAction = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };
  let uLag = 0.45;
  let kT = 22.0;
  let massHat = 0.725;
  let vxHat = 0, vyHat = 0, vzHat = 0;
  let dxHat = 0, dyHat = 0, dzHat = 0;
  let yawInt = 0;
  let rollLag = 0, pitchLag = 0;
  let rollTrim = 0, pitchTrim = 0;
  let startPos = { x: -2.1, y: 0.07, z: -1.65 };
  let gateExitX = -2.1, gateExitY = 0.5, gateExitZ = -1.65;

  function getDir(att) {
    const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
    const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
    const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
    const bodyX = sp * cr, bodyZ = -sr;
    return {
      x: cy * bodyX + sy * bodyZ,
      y: cp * cr,
      z: -sy * bodyX + cy * bodyZ,
    };
  }

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      if (!prevObs) {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
        startPos = { x: p.x, y: p.y, z: p.z };
        gateExitX = p.x; gateExitY = p.y; gateExitZ = p.z;
      } else {
        uLag += (lastAction.thrust - uLag) * (1 - Math.exp(-dt / 0.038));
        rollLag += (lastAction.roll - rollLag) * (1 - Math.exp(-dt / 0.05));
        pitchLag += (lastAction.pitch - pitchLag) * (1 - Math.exp(-dt / 0.05));

        const dirPrev = getDir(prevObs.att);
        const dirCurr = getDir(att);
        const dirAvg = {
          x: 0.5 * (dirPrev.x + dirCurr.x),
          y: 0.5 * (dirPrev.y + dirCurr.y),
          z: 0.5 * (dirPrev.z + dirCurr.z),
        };
        const drag = 0.42 / massHat;
        if (p.y > 0.09 && prevObs.pos.y > 0.09) {
          rollTrim = clamp(rollTrim + 0.5 * (rollLag - att.roll) * dt, -0.08, 0.08);
          pitchTrim = clamp(pitchTrim + 0.5 * (pitchLag - att.pitch) * dt, -0.08, 0.08);

          const ayModel = kT * uLag * dirAvg.y - 9.81 - drag * 0.5 * (prevObs.vel.y + v.y);
          vyHat += (ayModel + dyHat) * dt;
          const vyErr = v.y - vyHat;
          vyHat += 0.45 * vyErr;
          dyHat = clamp(dyHat + 7.5 * vyErr, -5.5, 5.5);

          if (uLag > 0.25 && dirAvg.y > 0.7) {
            kT = clamp(kT + 0.8 * dyHat * dt, 15.5, 27.5);
            massHat = clamp(15.2 / kT, 0.60, 0.85);
          }

          const fSpec = Math.max(0, kT * uLag + dyHat / Math.max(0.6, dirAvg.y));
          const axModel = fSpec * dirAvg.x - drag * 0.5 * (prevObs.vel.x + v.x);
          const azModel = fSpec * dirAvg.z - drag * 0.5 * (prevObs.vel.z + v.z);

          vxHat += (axModel + dxHat) * dt;
          const vxErr = v.x - vxHat;
          vxHat += 0.50 * vxErr;
          dxHat = clamp(dxHat + 11.0 * vxErr, -7.5, 7.5);

          vzHat += (azModel + dzHat) * dt;
          const vzErr = v.z - vzHat;
          vzHat += 0.50 * vzErr;
          dzHat = clamp(dzHat + 11.0 * vzErr, -7.5, 7.5);
        } else {
          vxHat = v.x; vyHat = v.y; vzHat = v.z;
        }
      }
      prevObs = {
        pos: { x: p.x, y: p.y, z: p.z },
        vel: { x: v.x, y: v.y, z: v.z },
        att: { roll: att.roll, pitch: att.pitch, yaw: att.yaw },
      };

      let target;
      let brakingAbort = false;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
          gateExitX = p.x;
          gateExitY = p.y;
          gateExitZ = p.z;
        }

        const alignX = gate.x - 0.36;
        const ez = Math.abs(p.z - gate.z);
        const ey = Math.abs(p.y - gate.y);
        const ezPred = Math.abs((p.z + 0.14 * vzHat) - gate.z);
        const eyPred = Math.abs((p.y + 0.14 * vyHat) - gate.y);

        if (phase === 'align') {
          if (obs.gateIndex === 0 && obs.t < 0.35) {
            // Vertical climb first so motor integral & mass estimator settle before horizontal pitch
            const s = clamp(obs.t / 0.35, 0, 1);
            target = {
              x: startPos.x + 0.25 * s * (alignX - startPos.x),
              y: startPos.y + s * (gate.y - startPos.y),
              z: startPos.z + 0.35 * s * (gate.z - startPos.z),
            };
          } else if (obs.gateIndex > 0 && p.x < gateExitX + 0.10) {
            target = { x: gateExitX + 0.25, y: gateExitY, z: gateExitZ };
          } else {
            target = { x: alignX, y: gate.y, z: gate.z };
          }
          if (
            Math.abs(alignX - p.x) < 0.12 &&
            ey < 0.075 &&
            ez < 0.045 &&
            ezPred < 0.055 &&
            Math.hypot(vxHat, vyHat, vzHat) < 0.32
          ) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 8) phase = 'cross';
        }

        if (phase === 'cross') {
          const distToGateX = gate.x - p.x;
          const timeToGate = distToGateX / Math.max(0.25, vxHat);
          const zAtGate = p.z + clamp(timeToGate, 0.05, 0.35) * vzHat;
          const yAtGate = p.y + clamp(timeToGate, 0.05, 0.35) * vyHat;

          if (
            distToGateX > 0.09 &&
            (ez > 0.068 || Math.abs(zAtGate - gate.z) > 0.078 || ey > 0.13 || Math.abs(yAtGate - gate.y) > 0.15)
          ) {
            phase = 'align';
            settle = 0;
            brakingAbort = true;
            target = { x: alignX, y: gate.y, z: gate.z };
          } else {
            target = { x: gate.x + 0.32, y: gate.y, z: gate.z };
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'pad_align';
          gateExitX = p.x;
          gateExitY = p.y;
          gateExitZ = p.z;
        }
        if (p.x < 1.35 + 0.12) {
          target = { x: 1.60, y: gateExitY, z: gateExitZ };
        } else {
          const distH = Math.hypot(pad.x - p.x, pad.z - p.z);
          const speedH = Math.hypot(vxHat, vzHat);
          target = { x: pad.x, y: clamp(0.25 + 0.7 * distH, 0.25, 0.95), z: pad.z };
          if (phase !== 'descend' && distH < 0.09 && speedH < 0.22 && p.y < 0.38) {
            phase = 'descend';
          }
          if (phase === 'descend') {
            if (distH > 0.135) phase = 'pad_align';
            else target.y = 0.025;
          }
        }
      }

      const drag = 0.42 / massHat;
      const maxAx = brakingAbort ? 4.5 : 2.8;
      const kpX = brakingAbort ? 6.0 : 3.9;
      const kdX = brakingAbort ? 4.5 : 3.3;

      const nearGate = obs.gateIndex < 3 && p.x > obs.nextGate.centre.x - 0.55;
      const kpZ = nearGate ? 6.2 : 4.2;
      const kdZ = nearGate ? 4.3 : 3.4;

      const ax = clamp(kpX * (target.x - p.x) - kdX * vxHat, -maxAx, 2.8) + drag * vxHat - dxHat;
      const az = clamp(kpZ * (target.z - p.z) - kdZ * vzHat, -3.8, 3.8) + drag * vzHat - dzHat;

      const ey = target.y - p.y;
      integralY = clamp(integralY + ey * 0.01, -0.5, 1.9);
      const ay = clamp(5.8 * ey - 3.8 * vyHat + 2.0 * integralY, -3.5, 3.6) + drag * vyHat - dyHat;

      const fy = Math.max(4.0, 9.81 + ay);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const fBodyX = cy * ax - sy * az;
      const fBodyZ = sy * ax + cy * az;

      const maxTilt = (obs.gateIndex === 3 && phase === 'descend' && p.y < 0.14) ? 0.14 : 0.48;
      let pitch = clamp(Math.atan2(fBodyX, fy) + pitchTrim, -maxTilt, maxTilt);
      let roll = clamp(Math.atan2(-fBodyZ, Math.hypot(fBodyX, fy)) + rollTrim, -maxTilt, maxTilt);

      // Keep collective thrust <= 0.74 so all 4 motors retain >= 26% attitude torque headroom
      let thrust = clamp(fy / (kT * Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch))), 0, 0.74);
      if (obs.gateIndex === 3 && phase === 'descend' && p.y <= 0.082 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.12) {
        thrust = 0.02;
        pitch = clamp(pitch, -0.10, 0.10);
        roll = clamp(roll, -0.10, 0.10);
      }

      yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-3.0 * att.yaw - 1.2 * yawInt, -2, 2);

      lastAction = { thrust, roll, pitch, yawRate };
      return lastAction;
    },
  };
}

